import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import "../styles/UserPages.css";

import API_BASE_URL from "../config";

const CreateListing = () => {
  const navigate = useNavigate();

  const [form, setForm] = useState({
    title: "",
    description: "",
    price: "",
    condition: "",
    category: "",
    image: null,
  });

  const [preview, setPreview] = useState(null);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setForm((prev) => ({ ...prev, [name]: value }));
  };

  const handleImageUpload = (e) => {
    const file = e.target.files[0];
    setForm((prev) => ({ ...prev, image: file }));
    setPreview(URL.createObjectURL(file));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!form.title || !form.description || !form.price || !form.condition || !form.category) {
      alert("Please fill out all fields.");
      return;
    }

    if (form.title.length > 50) {
      alert("Title too long. Max 50 characters.");
      return;
    }

    if (form.description.length > 200) {
      alert("Description too long. Max 200 characters.");
      return;
    }

    const userId = sessionStorage.getItem("userId");
    if (!userId) {
      alert("You must be logged in to create a listing.");
      return;
    }

    try {
      let imageBase64 = null;

      if (form.image) {
        const reader = new FileReader();
        reader.onloadend = async () => {
          imageBase64 = reader.result;

          const response = await fetch(`${API_BASE_URL}/api/listings`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({
              user_id: userId,
              title: form.title,
              description: form.description,
              price: form.price,
              condition: form.condition,
              category: form.category,
              image: imageBase64,
            }),
          });

          if (response.ok) {
            alert("Listing submitted!");
            setForm({
              title: "",
              description: "",
              price: "",
              condition: "",
              category: "",
              image: null,
            });
            setPreview(null);
          } else {
            alert("Failed to submit listing.");
          }
        };
        reader.readAsDataURL(form.image);
      } else {
        const response = await fetch(`${API_BASE_URL}/api/listings`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            user_id: userId,
            title: form.title,
            description: form.description,
            price: form.price,
            condition: form.condition,
            category: form.category,
            image: null,
          }),
        });

        if (response.ok) {
          alert("Listing submitted!");
          setForm({
            title: "",
            description: "",
            price: "",
            condition: "",
            category: "",
            image: null,
          });
          setPreview(null);
        } else {
          alert("Failed to submit listing.");
        }
      }
    } catch (err) {
      console.error("Submit error:", err);
      alert("An error occurred while submitting the listing.");
    }
  };

  return (
    <div>
      <Navbar />
      <div className="create-page-layout">
        <aside className="side-panel">
          <button
            className="back-button"
            onClick={() => navigate("/dashboard")}
          >
            ← Back to Dashboard
          </button>
        </aside>

        <main className="create-listing-wrapper">
          <h2>Create New Listing</h2>
          <form className="create-listing-form" onSubmit={handleSubmit}>
            <input
              type="text"
              name="title"
              placeholder="Item Title (max 20 characters)"
              value={form.title}
              onChange={handleChange}
              maxLength={20}
              required
            />
            <small>{form.title.length}/20 characters</small>

            <textarea
              name="description"
              placeholder="Item Description (max 30 characters)"
              value={form.description}
              onChange={handleChange}
              rows={5}
              maxLength={30}
              required
            />
            <small>{form.description.length}/30 characters</small>

            <input
              type="number"
              name="price"
              placeholder="Price (USD)"
              value={form.price}
              onChange={handleChange}
              required
            />

            <select name="condition" value={form.condition} onChange={handleChange} required>
              <option value="">Select Condition</option>
              <option value="new">New</option>
              <option value="like-new">Like New</option>
              <option value="good">Good</option>
              <option value="fair">Fair</option>
              <option value="used">Used</option>
            </select>

            <select name="category" value={form.category} onChange={handleChange} required>
              <option value="">Select Category</option>
              <option value="weights">Weights</option>
              <option value="machines">Machines</option>
              <option value="accessories">Accessories</option>
              <option value="apparel">Apparel</option>
            </select>

            <input type="file" accept="image/*" onChange={handleImageUpload} />

            {preview && <img src={preview} alt="Preview" className="image-preview" />}

            <button type="submit">Submit Listing</button>
          </form>
        </main>
      </div>
      <Footer />
    </div>
  );
};

export default CreateListing;
